def doc(lang, title, intro, secs):
    meta = ("Son güncelleme: " if lang == "tr" else "Last updated: ") + UPDATED[lang]
    out = f'<article class="doc"><h1>{title}</h1><p class="meta">{meta}</p>'
    if intro: out += f'<div class="box">{intro}</div>'
    for h, b in secs: out += f'<h2>{h}</h2>{b}'
    return out + '</article>'

